USE employee_db;

-- 1. Set Approved Headcounts on Departments
ON DUPLICATE KEY UPDATE approved_headcount = VALUES(approved_headcount);

-- 2. Seed Active Employees across Departments
ON DUPLICATE KEY UPDATE department_id = VALUES(department_id), status = 'Active', deleted_at = NULL;

-- 3. Seed Sample Leavers with termination dates
ON DUPLICATE KEY UPDATE department_id = VALUES(department_id), status = 'Inactive', termination_date = VALUES(termination_date), deleted_at = NULL;
